{
  "wire_schema": "role_benchmark.player_action.v3",
  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H_standard",
        "statement": "Period follows T = 2*pi*sqrt(length_m / 9.81), independent of bob_mass_kg and release_angle_deg in the small-angle range.",
        "confidence": 0.7
      },
      {
        "hypothesis_id": "H_linearL",
        "statement": "Period is proportional to length: T = 2.0 * length_m, independent of bob_mass_kg and release_angle_deg.",
        "confidence": 0.3
      }
    ]
  },
  "experiment": {
    "intent": "Measure period at a long length and high mass to discriminate sqrt-length dependence from linear-length dependence and to check for mass dependence.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 2.0,
      "bob_mass_kg": 1.0,
      "release_angle_deg": 10.0
    },
    "readouts": ["period_s"],
    "replicates": 20,
    "forecasts": {
      "H_standard": {"period_s": 2.837},
      "H_linearL": {"period_s": 4.0}
    }
  },
  "final": null
}
